/* An irregular fused cluster on a hex grid (axial coordinates, so adjacent
   hexagons always share a proper edge), with a few dangling open bonds at
   the perimeter — reads as a molecular structure diagram without needing
   to resemble cobalamin specifically. Three cells (not four) so the cluster
   is close enough to square to fill the canvas without clipping. */
const HEX_BONDS: [number, number, number, number][] = [
  [9.15, 15.43, 9.15, 24], [9.15, 15.43, 16.58, 11.14], [9.15, 24, 16.58, 28.29],
  [16.58, 11.14, 24, 15.43], [16.58, 28.29, 16.58, 36.86], [16.58, 28.29, 24, 24],
  [16.58, 36.86, 24, 41.14], [24, 15.43, 24, 24], [24, 15.43, 31.42, 11.14],
  [24, 24, 31.42, 28.29], [24, 41.14, 31.42, 36.86], [31.42, 11.14, 38.85, 15.43],
  [31.42, 28.29, 31.42, 36.86], [31.42, 28.29, 38.85, 24], [38.85, 15.43, 38.85, 24],
];

const HEX_ATOMS: [number, number][] = [
  [9.15, 15.43], [9.15, 24], [16.58, 11.14], [16.58, 28.29], [16.58, 36.86],
  [24, 15.43], [24, 24], [24, 41.14], [31.42, 11.14], [31.42, 28.29],
  [31.42, 36.86], [38.85, 15.43], [38.85, 24],
];

const HEX_OPEN_BONDS: [number, number, number, number][] = [
  [9.15, 24, 3.95, 24],
  [16.58, 11.14, 13.98, 6.64],
  [38.85, 15.43, 43.35, 12.83],
];

/** Molecule — a schematic hexagon-grid structure, not literally cobalamin. Vitamin B12 (A). */
export const MoleculeIcon = (p: IconProps) => (
  <Icon {...p} fill="none">
    {HEX_BONDS.map(([x1, y1, x2, y2]) => (
      <line key={`${x1}-${y1}-${x2}-${y2}`} x1={x1} y1={y1} x2={x2} y2={y2} stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" />
    ))}
    {HEX_OPEN_BONDS.map(([x1, y1, x2, y2]) => (
      <line key={`${x1}-${y1}-${x2}-${y2}`} x1={x1} y1={y1} x2={x2} y2={y2} stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" opacity={0.55} />
    ))}
    {HEX_ATOMS.map(([cx, cy]) => (
      <circle key={`${cx}-${cy}`} cx={cx} cy={cy} r={1.6} fill="currentColor" />
    ))}
    {HEX_OPEN_BONDS.map(([, , x2, y2]) => (
      <circle key={`${x2}-${y2}`} cx={x2} cy={y2} r={1.6} fill="currentColor" opacity={0.55} />
    ))}
  </Icon>
);

